-- Migration 012: Event registration self-cancellation (receipt-email link)
-- Date: 2026-10-17
--
-- Purpose:
-- Let a person cancel their own event registration through a link sent in the
-- registration receipt email, without changing the manual-review model:
--   - no email verification, no automatic confirmation of attendance,
--     no capacity logic, no waitlist.
--   - a cancelled registration is NEVER deleted; its status becomes
--     'cancelled' so the admin keeps the history.
--
-- Security model:
--   - The cancellation credential is a random token generated by the server.
--     Only its SHA-256 hash (hex) is stored here. The raw token exists only in
--     the receipt email link.
--   - The token hash is written in the SAME INSERT as the registration
--     (insert_event_registration_manual), so a registration cannot exist
--     without its token hash.
--   - Cancellation runs through a narrow SECURITY DEFINER function that is
--     given only the token hash. No public SELECT/UPDATE/DELETE is added and
--     RLS is not changed.
--
-- ROLLOUT ORDER: apply this migration BEFORE deploying the application code
-- that passes cancellation_token_hash_param. The new insert RPC replaces the
-- old 7-argument one (which is dropped below).

BEGIN;

-- 1. Columns
ALTER TABLE event_registrations
  ADD COLUMN IF NOT EXISTS cancellation_token_hash TEXT,
  ADD COLUMN IF NOT EXISTS cancelled_at TIMESTAMP WITH TIME ZONE;

COMMENT ON COLUMN event_registrations.cancellation_token_hash IS
  'SHA-256 hex hash of the self-cancellation token. The raw token is never stored.';
COMMENT ON COLUMN event_registrations.cancelled_at IS
  'Set when the registrant cancels through the emailed link.';

-- Lookup by token hash; unique so one hash can never match two registrations
CREATE UNIQUE INDEX IF NOT EXISTS idx_event_registrations_cancellation_token_hash
  ON event_registrations (cancellation_token_hash)
  WHERE cancellation_token_hash IS NOT NULL;

-- 2. Allow the new 'cancelled' status (superset of every status used so far,
--    including the legacy 'pending'/'verified' from migration 001)
ALTER TABLE event_registrations
  DROP CONSTRAINT IF EXISTS event_registrations_status_check;

ALTER TABLE event_registrations
  ADD CONSTRAINT event_registrations_status_check
  CHECK (status IN ('pending', 'verified', 'new', 'contacted', 'confirmed', 'declined', 'cancelled'));

-- 3. Insert RPC: same behavior as migration 006 plus an optional token hash.
--    The old 7-argument function is dropped so no second code path remains.
DROP FUNCTION IF EXISTS insert_event_registration_manual(
  BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT
);

CREATE OR REPLACE FUNCTION insert_event_registration_manual(
  event_id_param BIGINT,
  first_name_param TEXT,
  last_name_param TEXT,
  email_param TEXT,
  phone_param TEXT DEFAULT NULL,
  telegram_id_param TEXT DEFAULT NULL,
  comment_param TEXT DEFAULT NULL,
  cancellation_token_hash_param TEXT DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  new_registration_id BIGINT;
BEGIN
  -- Insert the registration with status='new' for the manual model.
  -- No exception handler: database errors (including unique_violation on
  -- duplicate event_id+email) propagate to the caller unchanged.
  INSERT INTO event_registrations (
    event_id,
    first_name,
    last_name,
    email,
    phone,
    telegram_id,
    comment,
    status,
    cancellation_token_hash
  ) VALUES (
    event_id_param,
    first_name_param,
    last_name_param,
    email_param,
    phone_param,
    telegram_id_param,
    comment_param,
    'new',
    cancellation_token_hash_param
  )
  RETURNING id INTO new_registration_id;

  RETURN new_registration_id;
END;
$$;

REVOKE ALL ON FUNCTION insert_event_registration_manual(
  BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT
) FROM PUBLIC;

REVOKE ALL ON FUNCTION insert_event_registration_manual(
  BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT
) FROM authenticated;

GRANT EXECUTE ON FUNCTION insert_event_registration_manual(
  BIGINT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT
) TO anon;

-- 4. Cancellation RPC
--    Input : SHA-256 hex hash of the token from the link.
--    Output: one row.
--      out_outcome = 'cancelled'          -> state changed now; details returned
--                                            so the server can notify the admin
--      out_outcome = 'already_cancelled'  -> nothing changed; no details returned
--      out_outcome = 'invalid'            -> unknown/malformed hash; no details
--    The row is locked (FOR UPDATE) so two simultaneous requests cannot both
--    report 'cancelled' (=> at most one admin notification).
--    Only status and cancelled_at/updated_at are modified. Event capacity,
--    event status and registration_status are untouched.
CREATE OR REPLACE FUNCTION cancel_event_registration_manual(
  token_hash_param TEXT
)
RETURNS TABLE (
  out_outcome TEXT,
  out_registration_id BIGINT,
  out_event_id BIGINT,
  out_first_name TEXT,
  out_last_name TEXT,
  out_email TEXT,
  out_previous_status TEXT,
  out_cancelled_at TIMESTAMP WITH TIME ZONE
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  reg public.event_registrations%ROWTYPE;
  cancelled_ts TIMESTAMP WITH TIME ZONE;
BEGIN
  IF token_hash_param IS NULL OR token_hash_param !~ '^[0-9a-f]{64}$' THEN
    RETURN QUERY SELECT 'invalid'::TEXT, NULL::BIGINT, NULL::BIGINT, NULL::TEXT,
      NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMP WITH TIME ZONE;
    RETURN;
  END IF;

  SELECT * INTO reg
  FROM public.event_registrations er
  WHERE er.cancellation_token_hash = token_hash_param
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::TEXT, NULL::BIGINT, NULL::BIGINT, NULL::TEXT,
      NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMP WITH TIME ZONE;
    RETURN;
  END IF;

  IF reg.status = 'cancelled' THEN
    RETURN QUERY SELECT 'already_cancelled'::TEXT, NULL::BIGINT, NULL::BIGINT, NULL::TEXT,
      NULL::TEXT, NULL::TEXT, NULL::TEXT, NULL::TIMESTAMP WITH TIME ZONE;
    RETURN;
  END IF;

  cancelled_ts := NOW();

  UPDATE public.event_registrations
  SET status = 'cancelled',
      cancelled_at = cancelled_ts,
      updated_at = cancelled_ts
  WHERE id = reg.id;

  RETURN QUERY SELECT 'cancelled'::TEXT, reg.id, reg.event_id, reg.first_name,
    reg.last_name, reg.email, reg.status, cancelled_ts;
END;
$$;

REVOKE ALL ON FUNCTION cancel_event_registration_manual(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION cancel_event_registration_manual(TEXT) FROM authenticated;
GRANT EXECUTE ON FUNCTION cancel_event_registration_manual(TEXT) TO anon;

COMMIT;
